from pathlib import Path
import pandas as pd,json,zipfile
from datetime import datetime
from zoneinfo import ZoneInfo
R=Path(__file__).resolve().parents[1]
def table(d):
 d=d.fillna('NA');return '| '+' | '.join(d.columns)+' |\n| '+' | '.join(['---']*len(d.columns))+' |\n'+'\n'.join('| '+' | '.join(map(str,row))+' |' for row in d.itertuples(index=False,name=None))
coverage=pd.read_csv(R/'tables/coverage.tsv',sep='\t');metrics=pd.read_csv(R/'tables/method_comparison.tsv',sep='\t');models=pd.read_csv(R/'tables/main_combinations.tsv',sep='\t');ident=pd.read_csv(R/'tables/identical_composition_diagnostic.tsv',sep='\t');paired=pd.read_csv(R/'tables/paired_comparisons_explicit_denominators.tsv',sep='\t')
lines=['# HD Epi-associated bin niches: dual methods, scales and references','',str(datetime.now(ZoneInfo('Asia/Shanghai'))),'','## Completion and denominator','', 'Eight main combinations executed on all evaluable shared anchors. Main model outputs are not confined to training/ROI. Training is 80000 anchors per ref/radius (20000 each C/D/UC/MPBC1); MPBC2 is projection-only. Niche counts describe anchors, not cells. Original inputs and labels are unchanged. MPBC original tissue mask remains unknown.','',table(models),'','## Shared anchors and support','',table(pd.read_csv(R/'tables/support_before_models.tsv',sep='\t')),'','## Native versus external assignment coverage','',table(pd.read_csv(R/'tables/coverage_wide.tsv',sep='\t')),'','## Native method comparison and full assignments','',table(metrics),'','The primary method comparison is native_T. Full_S contains A prediction and B external projection plus unresolved and is not a substitute. ARI/NMI/AMI measure partitions, not identity accuracy. A changes both representation (sqrt P) and clustering relative to B.','', '## Duplicate-composition diagnostic','',table(ident),'','Identical compositions split into multiple native B labels cannot be interpreted as biologically distinct environments. Their native labels are retained and flagged; all exact-profile training ties participate in external transfer. No-majority ties stay unresolved. This is not evidence that pure-Epi environments are invalid; it is an implementation/partition sensitivity of the discrete B solution. B labels should be treated as exploratory wherever this occurs.','', '## Scale and reference comparisons','',table(paired),'','50/200 are nested complete physical circles, not disjoint rings or independent replicates. Continuous common-four-type differences are in reference_coarse_composition.tsv; missing reference classes are not encoded as biological absences. Comparisons use common evaluable centers and disclose separate coverage.','', '## Biological and technical review','']
p=R/'INTERPRETATION.md';lines.append(p.read_text() if p.exists() else 'Interpretation review pending. Computation is not equivalent to completed spatial interpretation.')
lines+=['','## Files and targeted verification','', 'Each section contains anchor_manifest.parquet, r50/r200.parquet shared counts/proportions/support, geometric_coverage.parquet and original-neighbor marker support. Each blca_r50/blca_r200/hpca_r50/hpca_r200 directory contains labels.parquet (both methods, all shared centers), training_anchor_ids.tsv, A_model.joblib and B_training.npz. No eight copies of expression objects are made. tables/coverage_wide.tsv provides all 40 section/reference/radius/method coverage rows; tables/main_combinations.tsv provides eight completed main combinations.','',table(pd.read_csv(R/'tables/loader_validation.tsv',sep='\t')),'', 'Geometry, public API equivalence and native-label preservation records: geometry_validation.tsv, api_validation.json and validation.tsv. No computational main branch remains pending. Biological discreteness of B fine labels and MPBC tissue membership remain unresolved limitations.','', '## Reuse','', 'Dependencies: sibling hd_bin8_banksy_extension_v1, hd_bin8_comparison_v1, hd_bin8_banksy_v1. No expression copies are needed.','', '```r',f'root <- "{R}"','source(file.path(root,"code/load_result.R"))','x <- attach_hd_niches(x, root, "UC_SCC") # existing original Seurat object','```','', 'Python: code/load_result.py::attach_niches(adata, root, section), or load_niche_metadata(root,section). Non-anchor rows retain missing niche labels; epi_anchor=False. No circle members inherit their center label.','', 'code/ plus rerun.sh reproduce definitions and completed steps; models and P/counts remain on server. Review zip includes only summaries, reports, code, and key PNGs. Ordinary Visium correspondence is detailed in METHODS; no ordinary Visium or MP10 rerun.','']
(R/'REPORT.md').write_text('\n'.join(lines))
include=[]
for p in R.rglob('*'):
 if not p.is_file():continue
 rel=p.relative_to(R)
 if len(rel.parts)==1 and p.suffix in ['.md','.json','.sh','.tsv']:include.append(p)
 elif rel.parts[0]=='code' and p.suffix in ['.py','.R','.sh']:include.append(p)
 elif rel.parts[0]=='tables':include.append(p)
 elif p.name.startswith('method_crosstab_') or p.name in ['candidate_metrics.tsv','coverage.tsv','complete.json','projection_rules.json']:include.append(p)
 elif rel.parts[0]=='figures' and p.suffix=='.png' and ('methods_scales' in p.stem or 'ROI_typical' in p.stem or 'ROI_conflict_focus' in p.stem or p.stem=='parameter_stability' or p.stem.startswith('scale_flow_') or p.stem.startswith('composition_') and p.stem.endswith('_A')):include.append(p)
def pack():
 with zipfile.ZipFile(R/'review.zip','w',zipfile.ZIP_DEFLATED,compresslevel=6) as z:
  for p in include:z.write(p,p.relative_to(R))
pack();size=sum(p.stat().st_blocks*512 for p in R.rglob('*') if p.is_file());zsize=(R/'review.zip').stat().st_size
with (R/'REPORT.md').open('a') as f:f.write(f'\nNew allocated disk: {size/2**30:.3f} GiB (including isolated environment); review.zip {zsize/2**20:.1f} MiB.\n')
pack()
